def solve(text):
    def program():
        import sys
        sys.setrecursionlimit(10 ** 7)

        def input():
            return sys.stdin.readline().rstrip()

        def main():
            N, M = map(int, input().split())
            B = [list(map(int, input().split())) for _ in range(N)]
            for i in range(N):
                for j in range(M):
                    if B[i][j] % 7 > j + 1:
                        print('No')
                        return
            T = [[0] * M for _ in range(N)]
            start = B[0][0]
            for i in range(N):
                for j in range(M):
                    if i == 0 and j == 0:
                        T[0][0] = start
                    else:
                        T[i][j] = start + i * 7 + j
            if T == B:
                print('Yes')
            else:
                print('No')
        main()
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

