        n = int(input())
        s = [str(input()) for _ in range(n)]
        dic = {}
        for i in range(n):
            if s[i] == 'o':
                dic[i] = 0
            else:
                dic[i] = float('inf')
        for i in range(n):
            for k in range(n):
                if i > k and s[i][k] == 'o':
                    dic[i] = min(dic[i], dic[k] + 1)
        sorted_dic = sorted(dic.items(), key=lambda x: x[1], reverse=True)
        for i in sorted_dic:
            print(i[0] + 1, end=' ')
