import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        N, L, R = map(int, input().split())
        L -= 1
        R -= 1
        A = list(map(int, input().split()))
        A.sort()
        base = []
        for i in range(N):
            a = A[i]
            for e in base:
                a = min(a, a ^ e)
            for i in range(len(base)):
                base[i] = min(base[i], a ^ base[i])
            if a > 0:
                base.append(a)
        base.sort()
        ans = []
        for x in range(L, R + 1):
            res = 1
            for j in range(60):
                if x >> j & 1:
                    res ^= base[j]
            ans.append(res)
        return ans

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

